/** Where an item is drawn this frame, in profile pixels. `frame` is the layout box (automatic dimensions measured), `ink` what the item covers including effects; both are rectangles before rotation, each rotated by `rotation` degrees about its own centre. */
export interface ItemBounds {
  id: ItemId;
  frame: Rect;
  ink: Rect;
  rotation: number;
  /** Set when the item is drawn as a placeholder: unsupported (needs a newer engine), invalid (breaks a rule or limit), budget (over a document or process budget). A client treats a problem it doesn't know as a placeholder whose reason it can't name. */
  problem?: "unsupported" | "invalid" | "budget";
}

export interface Rect {
  x: number;
  y: number;
  /** Range: ≥ 0. */
  w: number;
  /** Range: ≥ 0. */
  h: number;
}

/** The JSON header of a frame message on /ws (docs/api.md): the document revision and tick the frame was drawn from, its scale and size, and where every item is. */
export interface FrameHeader {
  profileId: DocumentId;
  /** The document revision drawn. */
  rev: Revision;
  /**
   * The render tick the frame was drawn from (docs/identity.md). Within one subscription, frames with the same tick were drawn from the same tick snapshot, and tick numbers never go down.
   * Range: 0–9007199254740991.
   */
  tick: number;
  /**
   * The frame's number: unique within one run of the engine, and greater for a frame rendered later.
   * Range: 0–9007199254740991.
   */
  frameId: number;
  /**
   * How the payload after the header is encoded: `png`, the whole frame as a PNG.
   * Length: 1–32.
   */
  encoding: string;
  /**
   * Frame pixels per profile pixel: 0.1 or a multiple of 0.25 from 0.25 to 4. The subscription's scale rounded to a step of 0.25, then lowered while the frame would be over 16 Mpx (docs/api.md#frames).
   * Range: 0.1–4.
   */
  scale: number;
  /**
   * The frame's width in pixels: profileWidth × scale, rounded (docs/api.md#frames). pixelWidth × pixelHeight is at most 16,777,216.
   * Range: 1–65536.
   */
  pixelWidth: number;
  /**
   * The frame's height in pixels: profileHeight × scale, rounded (docs/api.md#frames).
   * Range: 1–65536.
   */
  pixelHeight: number;
  /**
   * The profile's canvas width at `rev`, in profile pixels.
   * Range: 1–16384.
   */
  profileWidth: number;
  /**
   * The profile's canvas height at `rev`, in profile pixels.
   * Range: 1–16384.
   */
  profileHeight: number;
  /** The bounds of every visible item that has bounds, from the same tick as the pixels, in document order: a group before its children (docs/geometry.md). Each id appears once. */
  itemBounds: ItemBounds[];
}

/** The `doc` message on /ws: the subscribed document's state. Sent when the subscription starts and after every change to the document or its state (a commit, undo, redo, revert or save, from any client). The engine keeps only the latest state to send: a client that falls behind gets the newest, so it may skip revisions, and the last one it gets is always current. It carries no content; the document at that revision is read with GET /api/profiles/{id}. */
export interface DocEvent {
  type: "doc";
  profileId: DocumentId;
  /** The document's tag, which `rev` belongs to (docs/api.md#a-documents-tag). */
  instance: InstanceId;
  /** The document's revision. */
  rev: Revision;
  /** The document differs from the saved one. */
  dirty: boolean;
  canUndo: boolean;
  canRedo: boolean;
}

/** What an engine supports (part of GET /api/session), by format string: every format it reads, each with the newest minor version of it the engine reads, the format's optional capabilities the engine has and the format's limits. A client ignores a format string it doesn't know. */
export type FormatSupport = { [key: string]: SupportedFormat };

/**
 * A format string: a format's name and its major version, such as `infopanel.scene/1` (docs/versioning.md).
 * Length: ≤ 64.
 * Pattern: `^[a-z][a-z0-9]*(\.[a-z][a-z0-9-]*)+/[1-9][0-9]{0,3}$`.
 */
export type FormatString = string;

/** One format an engine reads (formatSupport). */
export interface SupportedFormat {
  /**
   * The newest minor version of the format the engine reads, such as "1.0"; it reads every earlier one of the same major version.
   * Pattern: `^[0-9]+\.[0-9]+$`.
   */
  version: string;
  /** The format's optional capabilities the engine has (docs/versioning.md#capabilities-and-requires). A client ignores one it doesn't know. */
  capabilities: Capability[];
  /** The format's limits, by name (docs/limits.md says which format each belongs to). A client ignores a name it doesn't know. */
  limits: { [key: string]: number };
}

/** POST /api/tokens (the session token only): a new integration token with a name and scopes. Answered 201 with createdToken, the only answer that carries the token's secret (docs/api.md#authentication). */
export interface CreateTokenRequest {
  name: TokenName;
  /** What the token may do: `read`, `edit` or both. `edit` implies `read`, and the token is answered and listed with both. */
  scopes: TokenScopes;
}

/** An integration token, without its secret: GET /api/tokens (the session token only) answers an array of these, oldest first. The session token is never listed. */
export interface TokenInfo {
  id: TokenId;
  name: TokenName;
  /** The token's kind: `integration`, the only kind the API creates and lists. */
  kind: "integration";
  /** What the token may do: always `read`, and `edit` when it may change profiles, documents and blobs. */
  scopes: TokenScopes;
  /** When the token was created. */
  created: Timestamp;
  /** When the token last authenticated a request, kept to within a minute; absent when it never has. */
  lastUsed?: Timestamp;
}

/** 201 to POST /api/tokens: the new token's tokenInfo members and its secret, `token`, which no other answer carries and the engine doesn't keep (it stores only a hash). */
export interface CreatedToken {
  id: TokenId;
  name: TokenName;
  kind: "integration";
  scopes: TokenScopes;
  created: Timestamp;
  lastUsed?: Timestamp;
  /**
   * The secret, sent as `Authorization: Bearer {token}` or on /ws like the session token: `ipi_` and 43 base64url characters (256 random bits).
   * Pattern: `^ipi_[A-Za-z0-9_-]{43}$`.
   */
  token: string;
}

/**
 * An integration token's id, used to revoke it (DELETE /api/tokens/{id}): 32 lower-case hex digits. Not a secret.
 * Pattern: `^[0-9a-f]{32}$`.
 */
export type TokenId = string;

/**
 * A token's name, for people: 1 to 64 letters, digits, spaces, dots, underscores and hyphens, without a space at either end.
 * Length: 1–64.
 * Pattern: `^[A-Za-z0-9._-]([A-Za-z0-9 ._-]{0,62}[A-Za-z0-9._-])?$`.
 */
export type TokenName = string;

/**
 * Items: 1–2.
 * Unique items.
 */
export type TokenScopes = ("read" | "edit")[];

/**
 * A UTC time to the second (RFC 3339), such as "2026-10-27T09:30:00Z".
 * Pattern: `^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$`.
 */
export type Timestamp = string;

/** 403 application/problem+json: the token is valid but lacks the scope the request needs: `read` or `edit`, or `session` for what only the session token may do (signing in, the token endpoints, the engine settings, the recent log entries, opening the engine's folders). A missing, unknown or revoked token is answered 401 instead (docs/api.md#authentication). */
export interface ScopeProblem {
  type?: string;
  title?: string;
  detail?: string;
  status: 403;
  code: "scope";
  /** What the request needs. A client shows a scope it doesn't know by its name: the request is refused all the same. */
  scope: "read" | "edit" | "session";
}

/** application/problem+json (RFC 9457) for an error without a definition of its own: 400 (a query parameter that isn't a whole number, GET /ws without a WebSocket upgrade), 401 (no valid token), 403 (a request from an origin the engine doesn't accept), 404 (no such profile, blob, token, folder or endpoint), 405, 413 (a blob over mediaBytes) and 500 (an engine error, a folder the engine couldn't open, or displays it couldn't list). Its members are for people; a client acts on the status (docs/api.md#errors). */
export interface Problem {
  /** A URI for the kind of error: the HTTP status's section of RFC 9110. */
  type?: string;
  /** The HTTP status's reason phrase, such as "Not Found". */
  title: string;
  /**
   * The response's HTTP status.
   * Range: 400–599.
   */
  status: number;
  /** What went wrong, for people. */
  detail?: string;
  /** The request's trace id. */
  traceId?: string;
}

/** One sensor in GET /api/sensors, an array of these: a sensor the engine's sources offer, with the `key` a binding names (docs/bindings.md) and its status now. */
export interface SensorEntry {
  /**
   * The sensor's key, as a binding's `key` names it. Opaque.
   * Length: ≥ 1.
   */
  key: string;
  /** The id of the source that offers the sensor. */
  source: string;
  /** The group the source lists the sensor in (a device, say), for people. */
  group: string;
  /** The sensor's name, for people. */
  name: string;
  /** The unit of its values, for people ("°C", "%"); empty when it has none. */
  unit: string;
  /** `live` (a current reading), `stale` (a reading older than the source normally updates, the last value kept), `unavailable` (no reading), `denied` (the operating system refused the engine access to the sensor), `simulated` (no source handles the key; the engine simulates it, in mock mode only) or `missing` (the key isn't well formed). A scene input bound to the sensor reads it as docs/bindings.md#status maps it. A client treats a status it doesn't know as no reading. */
  status: "live" | "stale" | "unavailable" | "denied" | "simulated" | "missing";
}

/** One reading in GET /api/sensors/values, an array of these: every listed sensor (sensorEntry) that has a reading now, in list order. A sensor without one is left out. */
export interface SensorValue {
  /**
   * The sensor's key (sensorEntry).
   * Length: ≥ 1.
   */
  key: string;
  /** The current value (the last one when the reading is stale). A value that isn't a finite number is 0. */
  now: number;
  /** The lowest value the source has reported. */
  min: number;
  /** The highest value the source has reported. */
  max: number;
  /** The average of the values the source has reported. */
  avg: number;
  /** The unit of its values, for people; empty when it has none. */
  unit: string;
  /** A text or table sensor's text ("" for a table without one); absent for a number sensor. */
  text?: string;
  /**
   * With `?history=n` (n of 1 or more): a number sensor's last n samples at most, oldest first, one every `graphRate` milliseconds (engineSettings; one a second by default, docs/bindings.md#history). Absent otherwise, and for a text or table sensor.
   * Items: ≤ 4096.
   */
  history?: number[];
  /** `live`, or `stale` for the last value of a sensor that has stopped updating. A client treats a status it doesn't know as no reading. */
  status: "live" | "stale";
}

/** GET /api/settings, and the answer to PATCH /api/settings: the engine settings in effect, each the value set or its default, with how many changes this run made to the stored settings and whether the engine could read them (docs/api.md#settings). `status` tells the two shapes apart: `ok` without a `problem` (engineSettingsOk), or the settings the engine couldn't read with the `problem` (engineSettingsProblem). Read tolerantly: a later engine may add settings, and a client ignores members it doesn't know. A client treats a status it doesn't know as settings it can't change, and shows the `problem` when one comes. */
export type EngineSettings = EngineSettingsOk | EngineSettingsProblem;

/** The engine read its stored settings (or had none), and they can be changed: no `problem`. */
export interface EngineSettingsOk {
  status: "ok";
  /**
   * How many changes this run of the engine made to the stored settings: 0 when it starts, one more after each change that changed them. A value equal to its default is stored, and `null` removes one, so either counts though the value in effect stays the same; a change that leaves the stored settings as they were (the value a setting already has, `null` for one that isn't set, `{}`) doesn't count. It counts within the run the session's and hello's `instance` name, and starts again at 0 when the engine restarts.
   * Range: 0–9007199254740991.
   */
  version: number;
  /**
   * Frames a second for every output without a rate of its own: 1 to 60, 15 by default. The preview socket keeps its own (subscribeMessage's `maxFps`).
   * Range: 1–60.
   */
  frameRate: number;
  /**
   * Milliseconds between the samples of the sensor history: 100 to 3000, 1000 by default.
   * Range: 100–3000.
   */
  graphRate: number;
  logLevel: LogLevel;
  sources: SettingsSources;
  /** Each client's own preferences, by client name, as the client set them: the engine keeps them and never interprets them (docs/api.md#client-preferences). Empty when no client keeps any. */
  clients: { [key: string]: { [key: string]: JsonValue } | JsonValue[] | string | number | boolean };
}

/** The engine couldn't read its stored settings when it started: the defaults are in effect, `problem` says why, and every change is refused (409 settingsStatusProblem) until the stored settings are fixed or removed and the engine restarts. */
export interface EngineSettingsProblem {
  /** `unreadable`: the engine couldn't read its stored settings; `unsupported`: they are another major version's. A client treats a status it doesn't know as settings it can't change. */
  status: "unreadable" | "unsupported";
  /** Why the engine couldn't read its stored settings, with a JSON pointer into them. */
  problem: ValidationError;
  /**
   * How many changes this run of the engine made to the stored settings: 0 when it starts, one more after each change that changed them. A value equal to its default is stored, and `null` removes one, so either counts though the value in effect stays the same; a change that leaves the stored settings as they were (the value a setting already has, `null` for one that isn't set, `{}`) doesn't count. It counts within the run the session's and hello's `instance` name, and starts again at 0 when the engine restarts.
   * Range: 0–9007199254740991.
   */
  version: number;
  /**
   * Frames a second for every output without a rate of its own: 1 to 60, 15 by default. The preview socket keeps its own (subscribeMessage's `maxFps`).
   * Range: 1–60.
   */
  frameRate: number;
  /**
   * Milliseconds between the samples of the sensor history: 100 to 3000, 1000 by default.
   * Range: 100–3000.
   */
  graphRate: number;
  logLevel: LogLevel;
  sources: SettingsSources;
  /** Each client's own preferences, by client name, as the client set them: the engine keeps them and never interprets them (docs/api.md#client-preferences). Empty when no client keeps any. */
  clients: { [key: string]: { [key: string]: JsonValue } | JsonValue[] | string | number | boolean };
}

/** The settings of the engine's sensor sources, by source. */
export interface SettingsSources {
  libre: LibreSettings;
}

/** The settings of the LibreHardwareMonitor sensor source (on Windows): whether it reads sensors, whether it reads storage drives, and how often. An engine keeps them whether or not it has the source. */
export interface LibreSettings {
  /** Whether the source reads sensors; true by default. */
  enabled: boolean;
  /** Whether it reads storage drives' sensors; true by default. */
  storage: boolean;
  /**
   * Seconds between its reads of storage drives: 1 to 300, 30 by default.
   * Range: 1–300.
   */
  storageInterval: number;
}

/** How much the engine logs: the least severe entries it writes to its log, from `debug` (everything) through `information` and `warning` to `error` (errors only). A client shows a level it doesn't know by its name. */
export type LogLevel = "debug" | "information" | "warning" | "error";

/**
 * A client's name for its preferences (engineSettings' `clients`): 1 to 64 letters, digits, dots, underscores and hyphens. A client picks a name of its own, such as its product's name in lower case.
 * Pattern: `^[A-Za-z0-9._-]{1,64}$`.
 */
export type ClientName = string;

/** PATCH /api/settings: the settings to change (docs/api.md#changing-settings). A member given sets that setting, `null` sets it back to its default, and a setting left out keeps its value; `sources`, `sources.libre` and `clients` are merged member by member, each client's preferences set or removed whole. Closed: a member the engine doesn't know is refused. At most `settingsRequestBytes` as received, and the settings it makes are held to the settings limits (docs/limits.md#settings-limits). */
export interface SettingsChange {
  /**
   * Frames a second, 1 to 60 (engineSettings).
   * Range: 1–60.
   */
  frameRate?: number | null;
  /**
   * Milliseconds between history samples, 100 to 3000 (engineSettings).
   * Range: 100–3000.
   */
  graphRate?: number | null;
  logLevel?: LogLevel | null;
  sources?: {
    libre?: {
      enabled?: boolean | null;
      storage?: boolean | null;
      /**
       * Seconds, 1 to 300 (libreSettings).
       * Range: 1–300.
       */
      storageInterval?: number | null;
    };
  };
  /** Client preferences to set, each whole, or to remove (`null`), by client name; the other clients' are kept. */
  clients?: { [key: string]: { [key: string]: JsonValue } | JsonValue[] | string | number | boolean | null };
}

/** 409 application/problem+json to PATCH /api/settings: the engine couldn't read its stored settings when it started (`unreadable`), or they are another major version's (`unsupported`), so it changes none of them until they are fixed or removed and the engine restarts. Nothing was changed. */
export interface SettingsStatusProblem {
  type?: string;
  title?: string;
  detail?: string;
  status: 409;
  /** The settings' status (engineSettings). A client treats a status it doesn't know as settings it can't change. */
  code: "unreadable" | "unsupported";
  /** The settings' `problem` (engineSettings). */
  problem: ValidationError;
}

/** GET /api/logs: the engine's recent log entries newer than the request's `after`, oldest first, and the `seq` of the newest entry it has logged (docs/api.md#logs). A client polls with `after` set to the `latest` it last read. Read tolerantly: a client ignores members it doesn't know. */
export interface LogPage {
  /**
   * The kept entries whose `seq` is greater than `after` (every kept entry without it), oldest first: at most the newest 2,000 of the run. When the first one's `seq` isn't `after` + 1, the engine dropped the entries between.
   * Items: ≤ 2000.
   */
  entries: LogEntry[];
  /**
   * The `seq` of the newest entry this run of the engine has logged, kept or not; 0 before the first. It belongs to the run the session's and hello's `instance` name.
   * Range: 0–9007199254740991.
   */
  latest: number;
}

/** One of the engine's recent log entries, as its log file has it (docs/api.md#logs). `source`, `message` and `exception` are text for people, never a contract: a client shows them and never parses them. */
export interface LogEntry {
  /**
   * The entry's number: 1 for the run's first entry, one more for each entry after it, within the run the session's and hello's `instance` name.
   * Range: 1–9007199254740991.
   */
  seq: number;
  /**
   * When it was logged: RFC 3339 with milliseconds and the engine's offset from UTC, such as "2026-10-30T09:30:00.125+08:00".
   * Pattern: `^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}(Z|[+-][0-9]{2}:[0-9]{2})$`.
   */
  time: string;
  /** How severe it is, from `verbose` through `debug`, `information` and `warning` to `error` and `fatal`. A client treats a level it doesn't know as `information`. */
  level: "verbose" | "debug" | "information" | "warning" | "error" | "fatal";
  /**
   * The part of the engine that logged it, for people, or empty; one longer than 256 characters is cut, ending in "…".
   * Length: ≤ 256.
   */
  source: string;
  /**
   * What it says, for people; one longer than 4,096 characters is cut, ending in "…".
   * Length: ≤ 4096.
   */
  message: string;
  /**
   * The error it records, as text for people, when there is one; one longer than 8,192 characters is cut, ending in "…".
   * Length: ≤ 8192.
   */
  exception?: string;
}

/** GET /api/displays: the displays of the computer the engine runs on, read when the request came (docs/api.md#displays). Read tolerantly: a client ignores members it doesn't know. */
export interface DisplayList {
  /** Whether this engine shows desktop windows, and so can list the displays. When false, `displays` is empty: a client tells "no displays" (true, and empty) from "this engine can't list them". */
  supported: boolean;
  /** The displays, the primary one first, then in the order the system gives them. */
  displays: DisplayInfo[];
}

/** One display (docs/api.md#displays). `name`, `width`, `height`, `x` and `y` are exactly the `displayMatch` a profile's `window.display` takes to put its window on this display (urn:infopanel:document:1#/$defs/displayMatch). */
export interface DisplayInfo {
  /**
   * The name the engine matches the display by, at most 256 characters (a longer one is cut).
   * Length: ≤ 256.
   */
  name: string;
  /**
   * The display's width in its own pixels.
   * Range: 0–1000000.
   */
  width: number;
  /**
   * The display's height in its own pixels.
   * Range: 0–1000000.
   */
  height: number;
  /**
   * The display's left edge in the desktop's own coordinates (points on macOS, not pixels on a scaled display).
   * Range: -1000000–1000000.
   */
  x: number;
  /**
   * The display's top edge in the desktop's own coordinates (points on macOS, not pixels on a scaled display).
   * Range: -1000000–1000000.
   */
  y: number;
  /**
   * The display's name for people, at most 256 characters (a longer one is cut): the same as `name` where the system has one name for it, else the name the system shows people.
   * Length: ≤ 256.
   */
  label: string;
  /**
   * The display's pixels per unit of the desktop's own coordinates (2 on a Retina display on macOS).
   * Range: > 0.
   */
  scale: number;
  /** Whether it is the primary display (the main one, where a window without `display` goes). Only the first display listed is. */
  primary: boolean;
}

/** A text message a client sends on /ws (docs/api.md#the-preview-socket): a JSON object of at most 4,096 bytes in UTF-8, with a `type`. `auth` is only the first message, when the token wasn't offered as a subprotocol. Closed, as request bodies are (docs/versioning.md#unknown-members-and-values): the engine refuses a message with a member its definition doesn't have, as any other message it can't act on, with an error message (an `auth` message: by closing the socket). */
export type ClientMessage = AuthMessage | SubscribeMessage | ViewMessage | UnsubscribeMessage;

/** The first message on /ws when no `auth.{token}` subprotocol was offered: the token, within 5 seconds of the upgrade. The engine sends nothing before it; a token it doesn't accept, any other message, or none in time closes the socket with 1008. */
export interface AuthMessage {
  type: "auth";
  /** The session token or an integration token (either has the `read` scope). */
  token: string;
}

/** Subscribes to a profile's document: its doc messages and its frames, at `scale` and at most `maxFps` frames a second. It ends the connection's earlier subscription. A profile that doesn't exist or can't be opened is answered with an error message. */
export interface SubscribeMessage {
  type: "subscribe";
  profileId: DocumentId;
  scale?: FrameRequestScale;
  maxFps?: FrameRequestFps;
}

/** Changes the current subscription's scale or frame rate; a member left out keeps its value. Without a subscription it is answered with an error message. */
export interface ViewMessage {
  type: "view";
  scale?: FrameRequestScale;
  maxFps?: FrameRequestFps;
}

/** Ends the subscription: no more doc messages or frames until the next subscribe. */
export interface UnsubscribeMessage {
  type: "unsubscribe";
}

/**
 * The frame's pixels per profile pixel asked for, before the engine rounds and limits it (docs/api.md#frame-size). 1 when a subscribe leaves it out.
 * Range: > 0.
 */
export type FrameRequestScale = number;

/**
 * The most frames a second the client wants. 30 when a subscribe leaves it out; the engine draws at most 60.
 * Range: 1–2147483647.
 */
export type FrameRequestFps = number;

/** A text message the engine sends on /ws (docs/api.md#the-preview-socket): a JSON object with a `type`. Frames are binary messages (frameHeader). Read tolerantly (docs/versioning.md#unknown-members-and-values): a client ignores a type and members it doesn't know. */
export type ServerMessage = HelloMessage | DocEvent | ProfilesMessage | SettingsMessage | ErrorMessage;

/** The engine's first message on /ws, once the connection is authenticated. */
export interface HelloMessage {
  type: "hello";
  /**
   * The engine API's version, as GET /api/session gives it.
   * Range: ≥ 1.
   */
  protocol: number;
  /** This run of the engine, as GET /api/session gives it: another than the client saw before means the engine restarted. */
  instance: InstanceId;
}

/** The profile list changed: a profile was created, duplicated or deleted, by any client. The client reads GET /api/profiles. The engine keeps only the newest to send. */
export interface ProfilesMessage {
  type: "profiles";
  /**
   * How many times the list has changed in this run of the engine: greater for a later change.
   * Range: 1–9007199254740991.
   */
  version: number;
}

/** The engine settings changed: a change that changed the stored settings, by any client (PATCH /api/settings). Sent to every socket authenticated with the session token, the only token that reads the settings. The client reads GET /api/settings. The engine keeps only the newest to send. */
export interface SettingsMessage {
  type: "settings";
  /**
   * The settings' `version` after the change (engineSettings): greater for a later change, within the run hello names.
   * Range: 1–9007199254740991.
   */
  version: number;
}

/** Something the engine couldn't do for the client: a message it can't act on (not JSON, binary, an unknown type, a member the message doesn't define or of the wrong type, a view without a subscription), or a subscription to a profile that doesn't exist, can't be opened or previewed, or was deleted. The connection stays open. */
export interface ErrorMessage {
  type: "error";
  /**
   * What went wrong, for a client to act on (docs/api.md#errors-on-the-socket): `json`, `limit.jsonDepth` or `schema` for a message the engine can't act on, `subscription.missing` for a view without a subscription, `profile.*` for a subscription that didn't start or has ended. A later engine may add codes: a client handles a code it doesn't know by its family, else as a message the engine didn't act on (docs/versioning.md#error-codes-and-paths).
   * Length: ≥ 1.
   */
  code: string;
  /** The JSON pointer to what the error is about in the client message it answers: "" for the whole message, or when it answers none (a subscription that ended). */
  path: string;
  /** What went wrong, for people: display text, never read by a client. */
  message: string;
}

/** GET and PUT /api/import/v1: the 1.x migration (docs/import.md#migrating-a-1x-folder): its state, the 1.x folder the engine reads, the run-once record once there is one, and the folder's profiles, settings and diagnostics when it has 1.x data. Read tolerantly: a client ignores members it doesn't know. */
export interface V1Migration {
  /** `none` (the folder has no 1.x data), `pending` (1.x data and no record: not migrated yet) or `done` (a record, or one the engine can't read: the migration never runs on its own twice). A client treats a state it doesn't know as `done`: it doesn't migrate on its own. */
  state: "none" | "pending" | "done";
  /**
   * The 1.x folder the engine reads, as a full path. The engine only reads it.
   * Length: ≥ 1.
   */
  folder: string;
  /** The run-once record, when there is one the engine can read. */
  record?: V1MigrationRecord;
  /** The folder's profiles, in 1.x order, when it has 1.x data (at most `v1Profiles`, docs/limits.md#1x-import-limits). */
  profiles?: V1ProfileSummary[];
  /** The folder's settings, when it has 1.x data whose settings can be read (and isn't 1.1.x data). */
  settings?: V1Settings;
  /**
   * What was found reading the folder and the record (docs/import.md#diagnostics): at most `diagnostics`, then one `more`.
   * Items: ≤ 1001.
   */
  diagnostics?: ImportDiagnostic[];
}

/** PUT /api/import/v1: what a migration did, as a client reports it; the engine stores it as the run-once record (docs/import.md#the-record), adding the time and the folder. At most `recordOutcomes` outcomes, and at most `recordBytes` as received and as stored (docs/limits.md#1x-import-limits). */
export interface V1MigrationRequest {
  /** One outcome per 1.x profile the migration dealt with, in any order. */
  profiles: V1MigrationOutcome[];
  /** Whether the client applied the 1.x settings (`imported`) or not (`skipped`). A client reading it treats a value it doesn't know as `skipped`. */
  settings: "imported" | "skipped";
}

/** The run-once record: what a migration did, as a client reported it, with when the engine stored it and the 1.x folder it read. */
export interface V1MigrationRecord {
  /** When the engine stored the record, in UTC to the second. */
  completed: Timestamp;
  /**
   * The 1.x folder the engine read then, as a full path.
   * Length: ≥ 1.
   */
  folder: string;
  /** Items: ≤ 1000. */
  profiles: V1MigrationOutcome[];
  /** Whether the client applied the 1.x settings (`imported`) or not (`skipped`). A client treats a value it doesn't know as `skipped`. */
  settings: "imported" | "skipped";
}

/** What a migration did with one 1.x profile. */
export interface V1MigrationOutcome {
  /** The 1.x profile's Guid, in lower case. */
  v1Id: DocumentId;
  /** The profile created from it, or null when none was. */
  id: DocumentId | null;
  /** `imported`, `skipped` (the user left it out) or `failed`. A client treats an outcome it doesn't know as `failed`. */
  outcome: "imported" | "skipped" | "failed";
  /**
   * Why, for people: display text.
   * Length: ≤ 256.
   */
  reason?: string;
}

/** A profile of the 1.x folder's profile list, as 1.x lists it. */
export interface V1ProfileSummary {
  /** The 1.x profile's Guid, in lower case: what POST /api/import/v1/profiles/{v1Id} names. */
  id: DocumentId;
  /** Its name as stored (empty when it has none). */
  name: string;
  /**
   * Its canvas width as stored, which may be over a document's limit (a client clamps it).
   * Range: -2147483648–2147483647.
   */
  width: number;
  /**
   * Its canvas height as stored.
   * Range: -2147483648–2147483647.
   */
  height: number;
  /** Whether 1.x showed it as a window. */
  active: boolean;
}

/** The user data of the 1.x folder's settings (`settings.xml`, else `settings.xml.bak`), each value as 1.x would use it: an absent one is 1.x's default. Nothing is applied by reading it (docs/import.md#settings). */
export interface V1Settings {
  /**
   * The settings version: 131 from 1.3.1 on, 115 from 1.2.x. Absent when it doesn't parse.
   * Range: -2147483648–2147483647.
   */
  version?: number;
  /**
   * Frames a second, 1.x's default 15, within the engine setting's range.
   * Range: 1–60.
   */
  targetFrameRate: number;
  /**
   * Graph samples' interval in milliseconds, 1.x's default 1000, within the engine setting's range.
   * Range: 100–3000.
   */
  targetGraphUpdateRate: number;
  libre: V1LibreSettings;
  programSpecific: V1ProgramSpecificSettings;
  /** The panel devices of 1.x's device families, at most `v1Devices` per family. */
  devices: V1Device[];
  /** Per device family (as `v1Device.family` names it), whether 1.x drove several devices of it. */
  multiDevice: { [key: string]: boolean };
  /** 1.x's hotkeys, at most `v1Hotkeys`. */
  hotkeys: V1Hotkey[];
}

/** 1.x's LibreHardwareMonitor settings: whether it read sensors with it, and whether and how often it kept their readings. */
export interface V1LibreSettings {
  enabled: boolean;
  storage: boolean;
  /**
   * Seconds, within the engine setting's range.
   * Range: 1–300.
   */
  storageInterval: number;
}

/** Whether 1.x switched profiles by the program in front at all (its profiles' trigger apps), and whether it hid the other profiles then. */
export interface V1ProgramSpecificSettings {
  enabled: boolean;
  hideOthers: boolean;
}

/** A panel device of one of 1.x's device families: the 1.x profile it showed, and every simple element of the device as stored, as strings, at most `v1DeviceFields`. */
export interface V1Device {
  /** `beada`, `turing`, `lianLi`, `thermalright`, `thermaltake`, `jl`, `jonsbo` or `vmax`. A client leaves out a device of a family it doesn't know. */
  family: "beada" | "turing" | "lianLi" | "thermalright" | "thermaltake" | "jl" | "jonsbo" | "vmax";
  /** The 1.x profile it showed, its Guid in lower case; absent for none. */
  profile?: DocumentId;
  /** The device's elements by their 1.x names, each value as stored (at most `v1SettingLength` characters). */
  fields: { [key: string]: string };
}

/** A 1.x hotkey as stored: the keys, the device it targets and the 1.x profile it switches to. */
export interface V1Hotkey {
  modifiers: string;
  key: string;
  deviceType: string;
  deviceId: string;
  deviceLocation: string;
  /** The 1.x profile it switches to, its Guid in lower case; absent for none. */
  profile?: DocumentId;
}

/** POST /api/import/v1/profiles/{v1Id} and POST /api/import/v1/archive: one 1.x profile, read without installing anything (the envelope, docs/import.md#the-envelope): its properties, its items as the 1.x item JSON, its guides, its image files stored as blobs, and what was found on the way. A client creates a profile from it with POST /api/profiles, choosing the profile's id. Read tolerantly: a client ignores members it doesn't know. */
export interface V1Profile {
  /** `folder` (a profile of the 1.x folder) or `archive` (a 1.x `.infopanel` file). A client treats a source it doesn't know as `archive`. */
  source: "folder" | "archive";
  /** The 1.x profile's Guid as stored, in lower case. It isn't a profile id of this engine: a client that creates a profile from the envelope chooses that. */
  id: DocumentId;
  profile: V1ProfileProps;
  targetWindow?: V1TargetWindow;
  /** The top-level items, in 1.x order, the first at the back (docs/import.md#items). */
  items: V1Item[];
  /** 1.x's guides, wherever they sat among the items. */
  guides: V1Guide[];
  /** One entry per image file the items name (gauge frames included), keyed by the items' `filePath` and `relativePath`. */
  assets: V1Asset[];
  /**
   * What was found reading the profile (docs/import.md#diagnostics): at most `diagnostics`, then one `more`.
   * Items: ≤ 1001.
   */
  diagnostics: ImportDiagnostic[];
}

/** Every member of the 1.x profile model, by its camelCase name, as stored. A string 1.x left null, or a number that isn't finite, is null. */
export interface V1ProfileProps {
  name: string | null;
  /**
   * As stored, which may be over a document's limit (a client clamps it, `import.size`).
   * Range: -2147483648–2147483647.
   */
  width: number;
  /** Range: -2147483648–2147483647. */
  height: number;
  showFps: boolean;
  drag: boolean;
  backgroundColor: string | null;
  /** Whether 1.x showed it as a window. A 1.x export writes the model's default, true. */
  active: boolean;
  openGL: boolean;
  fontScale: number | null;
  topmost: boolean;
  /** The profile's default font family (`import.font` when the engine doesn't have it). */
  font: string | null;
  /** Range: -2147483648–2147483647. */
  fontSize: number;
  color: string | null;
  /** Range: -2147483648–2147483647. */
  windowX: number;
  /** Range: -2147483648–2147483647. */
  windowY: number;
  resize: boolean;
  strictWindowMatching: boolean;
  /** The programs whose window in front shows the profile, as 1.x stored them (comma-separated). */
  triggerProcessNames: string | null;
  /** Whether it was selected in 1.x. */
  isSelected: boolean;
}

/** The display 1.x placed the profile's window on. */
export interface V1TargetWindow {
  /** Range: -2147483648–2147483647. */
  x: number;
  /** Range: -2147483648–2147483647. */
  y: number;
  /** Range: -2147483648–2147483647. */
  width: number;
  /** Range: -2147483648–2147483647. */
  height: number;
  /** The display's device name on Windows, such as "\\.\DISPLAY2". */
  deviceName?: string;
}

/** What the engine adds to a 1.x item: its sensor binding as this engine reads it now. */
export interface V1ItemMeta {
  sensor?: V1SensorMeta;
}

/** The sensor a 1.x item is bound to: its key in this engine and its status now (`import.sensor` when it has no reading). */
export interface V1SensorMeta {
  /**
   * The sensor's key, as a binding names it (docs/bindings.md).
   * Length: ≥ 1.
   */
  key: string;
  /** As `sensorEntry.status`: `live`, `stale`, `unavailable`, `denied`, `simulated` or `missing`. A client treats a status it doesn't know as no reading. */
  status: "live" | "stale" | "unavailable" | "denied" | "simulated" | "missing";
}

/** A 1.x guide (a line 1.x showed only while a profile was being designed, never on a panel): data for a client, not an item. A member 1.x left out has 1.x's default. */
export interface V1Guide {
  /** Range: -2147483648–2147483647. */
  x: number;
  /** Range: -2147483648–2147483647. */
  y: number;
  /** Range: -2147483648–2147483647. */
  length: number;
  color: string;
  /** Range: -2147483648–2147483647. */
  rotation: number;
  /** As stored; 1.x's default "DisplayItem" when absent. */
  name: string;
  /** As stored: a guide in a hidden group keeps its own value (`container` tells the group). */
  hidden: boolean;
  locked: boolean;
  /** The JSON pointer of the group's `children` the guide sat in (`/items/1/children`), in the answer's items; absent at the top level. */
  container?: string;
}

/** An image file the items name: the blob it was stored as, or why nothing was stored (docs/import.md#assets). */
export interface V1Asset {
  /** Exactly the items' `filePath`. */
  path: string;
  /** Exactly the items' `relativePath`: the path is inside the profile's assets. */
  relative: boolean;
  /** The stored blob, as POST /api/blobs answers it. */
  blob?: BlobInfo;
  /**
   * Why nothing was stored: an `import.asset.*` code (docs/import.md#diagnostics). A later engine may add codes: a client treats one it doesn't know as a file that wasn't stored.
   * Length: ≥ 1.
   */
  code?: string;
  /**
   * With `import.asset.media`: the media check's code or the limit's (`media.format`, `limit.mediaBytes`, `archive.expanded`, ...).
   * Length: ≥ 1.
   */
  reason?: string;
}

/** A problem found reading 1.x data, inside an otherwise readable answer (docs/import.md#diagnostics). */
export interface ImportDiagnostic {
  /** `error` (something wasn't read), `warning` (read, but not as 1.x had it) or `info`. A client treats a severity it doesn't know as `warning`. */
  severity: "error" | "warning" | "info";
  /**
   * A code of docs/import.md's catalogue (`import.*`), or `more`, which counts the diagnostics not listed. A later engine may add codes: a client handles a code it doesn't know by its severity (docs/versioning.md#error-codes-and-paths).
   * Length: ≥ 1.
   */
  code: string;
  /** The JSON pointer to what it is about, in the answer; "" for the whole. */
  path: string;
  /** What was found, for people: display text, never read by a client. */
  message: string;
  /** The 1.x file it was found in, as the folder or the archive names it (`profiles/{guid}.xml`, `Profile.xml`), when known. */
  file?: string;
  /**
   * The line in `file`, from 1, when known.
   * Range: 1–2147483647.
   */
  line?: number;
}

/** POST /api/import/archive: a profile archive opened and verified (docs/archive.md#importing): its document, to create a profile from with POST /api/profiles, the blobs it carried, each stored, and the blobs the document refers to that are neither in the archive nor stored here. Nothing else is stored or created. Read tolerantly: a client ignores members it doesn't know. */
export interface ArchiveContents {
  /** The archive's document, as it holds it: the shape a create takes. */
  document: ImportDocument;
  /** Each blob the archive carried, stored, as POST /api/blobs answers it, in the archive's order. */
  blobs: BlobInfo[];
  /** Blob ids the document refers to that the archive didn't carry and this engine doesn't store, in order: media naming one draws the missing-media placeholder until it is stored. */
  missing: BlobId[];
}

/** 409 application/problem+json to GET /api/profiles/{id}/archive: the profile's archive would be one its own import refuses, so it isn't made (docs/archive.md#exporting). Its errors carry the codes the import would give (`archive.entries`, `archive.expanded`), at "". */
export interface ExportProblem {
  type?: string;
  title?: string;
  detail?: string;
  status: 409;
  code: "export";
  /** Items: 1–101. */
  errors: ValidationError[];
}

// archive.schema.json (urn:infopanel:archive:1)

/**
 * ArchiveManifest
 *
 * infopanel.archive/1: the manifest of a profile archive (`.infopanel2`), its entry `manifest.json`, which an engine reads before anything else in the archive (docs/archive.md). Closed: a member this version doesn't define is refused; additions come under a capability in `requires`.
 */
export interface ArchiveManifest {
  /** The archive format and its major version. An engine that doesn't read the major version refuses the archive as unsupported. */
  format: "infopanel.archive/1";
  /**
   * Every archive capability beyond version 1.0 the archive uses (docs/versioning.md#capabilities-and-requires): an engine that lacks one refuses the archive as unsupported before reading the rest. Version 1.0 defines none.
   * Items: ≤ 32.
   * Unique items.
   */
  requires: Capability[];
  /**
   * The entries that hold the archive's profile documents: in version 1.0 exactly one, `document.json`. More than one would come under a capability.
   * Items: 1–1.
   */
  profiles: "document.json"[];
}

// common.schema.json (urn:infopanel:common:1)

/**
 * A capability id: a feature an engine may or may not support (see docs/versioning.md).
 * Length: ≤ 64.
 * Pattern: `^[a-z][a-z0-9]*(\.[a-z][a-z0-9-]*)*$`.
 */
export type Capability = string;

/**
 * The name of a scene input, value or state cell, or of an item's binding.
 * Pattern: `^[a-z][A-Za-z0-9_]{0,31}$`.
 */
export type Name = string;

/**
 * A scene node's instance id, unique within its scene.
 * Pattern: `^[A-Za-z_][A-Za-z0-9_.-]{0,63}$`.
 */
export type NodeId = string;

/**
 * An item's id, unique within its document. Chosen by whoever creates the item and never changed.
 * Pattern: `^[A-Za-z0-9_-]{1,64}$`.
 */
export type ItemId = string;

/**
 * A document's id: a UUID in lower case.
 * Pattern: `^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`.
 */
export type DocumentId = string;

/**
 * A blob (asset or other stored file) named by the SHA-256 of its bytes.
 * Pattern: `^sha256:[0-9a-f]{64}$`.
 */
export type BlobId = string;

/**
 * An sRGB colour, #RRGGBB or #RRGGBBAA (alpha last, not premultiplied).
 * Pattern: `^#(?:[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$`.
 */
export type ColorLiteral = string;

/**
 * A revision number, assigned by the engine.
 * Range: 0–9007199254740991.
 */
export type Revision = number;

/**
 * A BCP 47 language tag such as de-CH: a language and up to four subtags, letters and digits only (no extensions).
 * Pattern: `^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8}){0,4}$`.
 */
export type LocaleTag = string;

/** A JSON object the engine stores and returns unchanged and never interprets. */
export type Opaque = { [key: string]: JsonValue };

// document.schema.json (urn:infopanel:document:1)

/**
 * Document
 *
 * One profile: its settings and a tree of items, each placed by the engine and drawn from its scene. Format infopanel.document/1; see docs/document.md. View state (selection, expansion, zoom) is never part of a document.
 */
export interface Document {
  format: "infopanel.document/1";
  /**
   * Document capabilities beyond version 1.0. An engine that lacks one doesn't open the document for editing (see docs/versioning.md).
   * Items: ≤ 32.
   * Unique items.
   */
  requires?: Capability[];
  id: DocumentId;
  /**
   * The document's revision: it goes up with every change (edits, undo, redo, revert).
   * Set by the engine; ignored when a client sends it.
   */
  rev?: Revision;
  profile: Profile;
  /** Top-level items in drawing order: the first is at the back. */
  items: Item[];
}

export interface Profile {
  /**
   * The document revision at which a profile field last changed.
   * Set by the engine; ignored when a client sends it.
   */
  rev?: Revision;
  /** Length: 1–256. */
  name: string;
  /**
   * Canvas width in pixels.
   * Range: 1–16384.
   */
  width: number;
  /**
   * Canvas height in pixels.
   * Range: 1–16384.
   */
  height: number;
  /**
   * Every frame starts as this colour; a transparent one lets a desktop window show what is behind it.
   * @default "#ffffffff"
   */
  background?: ColorLiteral;
  /**
   * Draw the engine's frame-rate overlay on every output.
   * @default false
   */
  statsOverlay?: boolean;
  /** The regional format numbers and dates are drawn in (see docs/expressions.md, Regional format). Absent: the PC's regional format. */
  locale?: LocaleTag;
  window?: WindowSettings;
  /**
   * Applications (process names) whose being in front should bring this profile up. Stored; acted on by engines that support it.
   * Items: ≤ 32.
   */
  triggerApps?: string[];
  /**
   * Editor-only guide lines: saved with the document and undone like any edit, never drawn on any output.
   * Items: ≤ 256.
   */
  guides?: Guide[];
  /** Client data kept with the document (for example defaults for new items); opaque to the engine. At most 64 KiB. */
  editor?: Opaque;
}

/** The profile's desktop window (one per profile), shown at one frame pixel per pixel of the display it is on, up to the 16,777,216-pixel frame cap, above which the frame is drawn smaller and stretched over the window (docs/document.md). */
export interface WindowSettings {
  /** Show the profile in a desktop window. */
  enabled: boolean;
  /**
   * Pixels from the left of the matched display.
   * Range: -1000000–1000000.
   * @default 0
   */
  x?: number;
  /**
   * Pixels from the top of the matched display.
   * Range: -1000000–1000000.
   * @default 0
   */
  y?: number;
  display?: DisplayMatch;
  /**
   * Hide the window when no display matches `display` exactly.
   * @default false
   */
  strict?: boolean;
  /** @default false */
  topmost?: boolean;
  /** @default true */
  draggable?: boolean;
  /** @default true */
  resizable?: boolean;
}

/** The display the window belongs on, matched by name and size in the display's pixels; x and y, in the desktop's own coordinates, tell displays of the same name and size apart. No exact match: hidden when strict, else the first display with the name, else the first with the size, else the main one. Absent: the main display (docs/document.md). */
export interface DisplayMatch {
  /** Length: ≤ 256. */
  name: string;
  /**
   * The display's width in its own pixels.
   * Range: 0–1000000.
   */
  width: number;
  /**
   * The display's height in its own pixels.
   * Range: 0–1000000.
   */
  height: number;
  /**
   * The display's left edge in the desktop's own coordinates (points on macOS, not pixels on a scaled display).
   * Range: -1000000–1000000.
   */
  x?: number;
  /**
   * The display's top edge in the desktop's own coordinates (points on macOS, not pixels on a scaled display).
   * Range: -1000000–1000000.
   */
  y?: number;
}

/** A guide line across the whole canvas: axis x is a vertical line at x = at, axis y a horizontal one at y = at. */
export interface Guide {
  axis: "x" | "y";
  /** Range: -1000000–1000000. */
  at: number;
}

export type Item = SceneItem | GroupItem;

/** An item that draws a scene, placed by `placement` in its parent's coordinates. */
export interface SceneItem {
  kind: "scene";
  id: ItemId;
  rev?: ItemRev;
  name?: ItemName;
  /** @default true */
  visible?: boolean;
  /**
   * Editors don't move or change a locked item; the engine doesn't enforce it.
   * @default false
   */
  locked?: boolean;
  placement: Placement;
  layout?: Layout;
  bindings?: Bindings;
  source?: Source;
  origin?: Origin;
  scene: Scene;
}

/** An item that holds other items. Its children are placed in its coordinates: the group's placement moves and rotates them as one. */
export interface GroupItem {
  kind: "group";
  id: ItemId;
  rev?: ItemRev;
  name?: ItemName;
  /**
   * false hides the group and everything in it.
   * @default true
   */
  visible?: boolean;
  /** @default false */
  locked?: boolean;
  placement: Placement;
  origin?: Origin;
  /** In drawing order: the first is at the back. */
  children: Item[];
}

/**
 * The document revision at which the item last changed. Ignored when a client inserts an item.
 * Set by the engine; ignored when a client sends it.
 */
export type ItemRev = Revision;

/**
 * A name for people (layer lists); not shown on outputs.
 * Length: ≤ 256.
 * @default ""
 */
export type ItemName = string;

/** Where the engine puts the item: its local origin (0, 0) at (x, y) in the parent's coordinates, rotated clockwise by `rotation` degrees about `pivot` (local coordinates). See docs/geometry.md. */
export interface Placement {
  /** Range: -1000000–1000000. */
  x: number;
  /** Range: -1000000–1000000. */
  y: number;
  /**
   * Range: -3600–3600.
   * @default 0
   */
  rotation?: number;
  /**
   * Absent: half the layout box's size on each axis where it is set, 0 where it is automatic (and (0, 0) for groups).
   * Items: ≥ 2.
   */
  pivot?: [number, number];
}

/** The item's layout box, (0, 0)–(w, h) in local coordinates; the scene reads it with {"op": "box"}. An absent dimension is automatic: the content decides it. A client that changes it usually sends a new scene too (setDesign). */
export interface Layout {
  /** Range: 0–16384. */
  w?: number;
  /** Range: 0–16384. */
  h?: number;
}

/** The sensor each scene input reads, by input name. Bindings for names the scene doesn't declare are kept and ignored. */
export type Bindings = { [key: string]: Binding };

export interface Binding {
  /**
   * A sensor key as the engine lists them (GET /api/sensors).
   * Length: 1–512.
   */
  key: string;
  /**
   * The statistic an input's `value` reads.
   * @default "now"
   */
  stat?: "now" | "min" | "max" | "avg";
}

/** How the client produced the scene, so it can produce it again. Opaque to the engine apart from this envelope: `format` names the client's own description in `data`; or `ref` is an opaque reference the engine never interprets, with the description kept elsewhere. `deps` lists stored blobs the description needs; the engine keeps them while any retained version of the document refers to them. */
export type Source = InlineSource | RefSource;

export interface InlineSource {
  /** Length: 1–128. */
  format: string;
  data?: JsonValue;
  deps?: SourceDeps;
}

export interface RefSource {
  /** Length: 1–512. */
  ref: string;
  data?: JsonValue;
  deps?: SourceDeps;
}

/**
 * The stored blobs the description needs, each once. They have no count of their own: `sourceBytes` bounds them (docs/limits.md).
 * Unique items.
 */
export type SourceDeps = BlobId[];

/** Where the item came from, recorded by the client; opaque to the engine, kept on copy. At most 4 KiB. */
export type Origin = Opaque;

// expression.schema.json (urn:infopanel:expression:1)

/** An expression of type number. */
export type NumberExpr = number | NumberUnaryOp | NumberBinaryOp | NumberVariadicOp | NumberTernaryOp | NumberIfOp | NumberStepsOp | NumberInputOp | HistoryOp | TimeOp | BoxOp | MeasureOp | DtOp | ValueRefOp | StateRefOp;

/** An expression of type string. */
export type StringExpr = string | ConcatOp | CaseOp | FormatOp | FormatTimeOp | StringInputOp | StringIfOp | StringStepsOp | ValueRefOp | StateRefOp;

/** An expression of type bool. */
export type BoolExpr = boolean | CompareOp | EqualOp | LogicOp | NotOp | BoolInputOp | BoolIfOp | BoolStepsOp | ValueRefOp | StateRefOp;

/** An expression of type color. A literal is #RRGGBB or #RRGGBBAA. */
export type ColorExpr = ColorLiteral | RgbaOp | AlphaOp | ColorLerpOp | ColorIfOp | ColorStepsOp | ValueRefOp | StateRefOp;

/** An expression of type number or string: numberExpr's and stringExpr's alternatives in one list, so `op` selects the operation and an error inside it keeps its own path. */
export type NumberOrStringExpr = number | string | NumberUnaryOp | NumberBinaryOp | NumberVariadicOp | NumberTernaryOp | NumberIfOp | NumberStepsOp | NumberInputOp | HistoryOp | TimeOp | BoxOp | MeasureOp | DtOp | ConcatOp | CaseOp | FormatOp | FormatTimeOp | StringInputOp | StringIfOp | StringStepsOp | ValueRefOp | StateRefOp;

/** An expression of any type. Its type is inferred (see docs/expressions.md); a string literal that is a colour literal is read as a colour where a colour is expected. */
export type AnyExpr = NumberExpr | StringExpr | BoolExpr | ColorExpr;

/** One number in, one number out: neg (−x), abs, floor, ceil, round (half away from zero), sqrt, exp, log (natural), sin and cos (of degrees). */
export interface NumberUnaryOp {
  op: "neg" | "abs" | "floor" | "ceil" | "round" | "sqrt" | "exp" | "log" | "sin" | "cos";
  /** Items: ≥ 1. */
  args: [NumberExpr];
}

/** sub (a − b), div (a ÷ b, 0 when b is 0), mod (floored: a − b·floor(a/b), 0 when b is 0), pow (a^b), atan2 (angle of the point (b, a) in degrees, args [y, x]). */
export interface NumberBinaryOp {
  op: "sub" | "div" | "mod" | "pow" | "atan2";
  /** Items: ≥ 2. */
  args: [NumberExpr, NumberExpr];
}

/** add, mul, min and max of 2 to 16 numbers. */
export interface NumberVariadicOp {
  op: "add" | "mul" | "min" | "max";
  /** Items: 2–16. */
  args: NumberExpr[];
}

/** clamp [x, lo, hi]; norm [x, lo, hi] = (x − lo) ÷ (hi − lo), 0 when hi = lo, not clamped; lerp [a, b, t] = a + (b − a)·t, not clamped. */
export interface NumberTernaryOp {
  op: "clamp" | "norm" | "lerp";
  /** Items: ≥ 3. */
  args: [NumberExpr, NumberExpr, NumberExpr];
}

/** lt, le, gt, ge: compare two numbers. */
export interface CompareOp {
  op: "lt" | "le" | "gt" | "ge";
  /** Items: ≥ 2. */
  args: [NumberExpr, NumberExpr];
}

/** eq, ne: compare two values as their common type, a string when both can be strings (see docs/expressions.md, Equality): numbers exactly, strings by code point, colours by their 8-digit form. */
export interface EqualOp {
  op: "eq" | "ne";
  /** Items: ≥ 2. */
  args: [AnyExpr, AnyExpr];
}

/** and, or of 2 to 16 bools. */
export interface LogicOp {
  op: "and" | "or";
  /** Items: 2–16. */
  args: BoolExpr[];
}

export interface NotOp {
  op: "not";
  /** Items: ≥ 1. */
  args: [BoolExpr];
}

/** Joins 1 to 32 strings. The result is cut to its first 4,096 Unicode scalar values. */
export interface ConcatOp {
  op: "concat";
  /** Items: 1–32. */
  args: StringExpr[];
}

/** upper, lower: Unicode simple case mapping, code point by code point, with no locale rules (see docs/expressions.md, Case mapping). The result is cut to its first 4,096 Unicode scalar values. */
export interface CaseOp {
  op: "upper" | "lower";
  /** Items: ≥ 1. */
  args: [StringExpr];
}

/** A number as text: rounded half away from zero to `decimals` places (0–6), with an optional group separator every three integer digits; a number given as text keeps its own digits. The result is cut to its first 4,096 Unicode scalar values. */
export interface FormatOp {
  op: "format";
  /** A number, or a number given as text: a string that is a plain decimal (an optional `-`, digits, and an optional `.` and digits) keeps its own digits and takes the separators; any other string is returned unchanged (see docs/expressions.md, Number formatting). */
  value: NumberOrStringExpr;
  /**
   * Rounded to an integer and clamped to 0–6; for a number only.
   * @default 0
   */
  decimals?: NumberExpr;
  /**
   * Insert `groupSeparator` between groups of three integer digits.
   * @default false
   */
  group?: BoolExpr;
  /**
   * Absent: the regional format's (see docs/expressions.md, Regional format).
   * Length: ≤ 4.
   */
  decimalSeparator?: string;
  /**
   * Absent: the regional format's (see docs/expressions.md, Regional format).
   * Length: ≤ 4.
   */
  groupSeparator?: string;
}

/** The tick's date and time as text, by a pattern (see docs/expressions.md, "Time patterns"). The result is cut to its first 4,096 Unicode scalar values. */
export interface FormatTimeOp {
  op: "formatTime";
  /** Length: 1–128. */
  pattern: string;
  /** A BCP 47 language tag for month and day names and the AM/PM marker. Absent: the regional format's (see docs/expressions.md, Regional format). */
  locale?: LocaleTag;
  zone?: TimeZone;
}

/**
 * An IANA time zone name such as Europe/Berlin. Absent: the engine's local zone.
 * Length: ≤ 64.
 * Pattern: `^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+){0,3}$`.
 */
export type TimeZone = string;

/** A number from the tick's clock. elapsed: seconds since the engine started rendering the document (monotonic). epoch: seconds since 1970-01-01T00:00:00Z. dayTime: seconds since local midnight, with fraction. year, month (1–12), day (1–31), weekday (1 = Monday … 7 = Sunday), hour (0–23), minute, second (0–59), millisecond (0–999): local calendar fields. */
export interface TimeOp {
  op: "time";
  field: "elapsed" | "epoch" | "dayTime" | "year" | "month" | "day" | "weekday" | "hour" | "minute" | "second" | "millisecond";
  zone?: TimeZone;
}

/** The item's layout box size in pixels (`w`, `h`; an automatic dimension reads as 0), or the item's rotation on the canvas in degrees (`rotation`: its placement rotation plus those of the groups it is in, not normalised; the rotation its bounds report). See docs/geometry.md. */
export interface BoxOp {
  op: "box";
  field: "w" | "h" | "rotation";
}

/** The measured width or height of a text node of this scene (by id), laid out this tick: the laid-out text (widest line, lines' height), not its box. Not allowed in state cells, nor where it would affect the layout of a text node that is measured (see docs/expressions.md, "Order of evaluation"). */
export interface MeasureOp {
  op: "measure";
  node: NodeId;
  field: "w" | "h";
}

/** Seconds since the previous state update. Only inside a state cell's `next`. */
export interface DtOp {
  op: "dt";
}

/** An aggregate over the last `count` history samples of a number input (newest last). No samples: 0. */
export interface HistoryOp {
  op: "history";
  input: Name;
  fn: "min" | "max" | "avg" | "first" | "last" | "count";
  /** Range: 1–4096. */
  count: number;
}

/** A number input's reading. value: the statistic the binding selects (now by default); now, min, max, avg: that statistic. An unbound or unavailable input reads 0. */
export interface NumberInputOp {
  op: "input";
  name: Name;
  /** @default "value" */
  field?: "value" | "now" | "min" | "max" | "avg";
}

/** An input's text: text (a text input's reading, or a table input's summary), unit (a number input's unit), status (unbound, live, stale, unavailable or denied). Unavailable text reads "". The result is cut to its first 4,096 Unicode scalar values. */
export interface StringInputOp {
  op: "input";
  name: Name;
  field: "text" | "unit" | "status";
}

/** Whether an input has a reading (status live or stale). */
export interface BoolInputOp {
  op: "input";
  name: Name;
  field: "available";
}

/** A named value of the scene (`values`). */
export interface ValueRefOp {
  op: "value";
  name: Name;
}

/** A state cell of the scene (`state`): its value this tick, or its previous value inside a cell's `next`. */
export interface StateRefOp {
  op: "state";
  name: Name;
}

/** A colour from red, green, blue (0–255) and alpha (0–1), each clamped, every channel rounded half away from zero to 0–255. */
export interface RgbaOp {
  op: "rgba";
  /** Items: ≥ 4. */
  args: [NumberExpr, NumberExpr, NumberExpr, NumberExpr];
}

/** The colour with its alpha replaced (0–1, clamped, rounded half away from zero to 0–255). */
export interface AlphaOp {
  op: "alpha";
  /** Items: ≥ 2. */
  args: [ColorExpr, NumberExpr];
}

/** Mixes two colours per channel in sRGB, unpremultiplied: a + (b − a)·t, t clamped to 0–1, each channel rounded half away from zero. */
export interface ColorLerpOp {
  op: "lerp";
  /** Items: ≥ 3. */
  args: [ColorExpr, ColorExpr, NumberExpr];
}

/** args [condition, then, else]. */
export interface NumberIfOp {
  op: "if";
  /** Items: ≥ 3. */
  args: [BoolExpr, NumberExpr, NumberExpr];
}

/** args [condition, then, else]. */
export interface StringIfOp {
  op: "if";
  /** Items: ≥ 3. */
  args: [BoolExpr, StringExpr, StringExpr];
}

/** args [condition, then, else]. */
export interface BoolIfOp {
  op: "if";
  /** Items: ≥ 3. */
  args: [BoolExpr, BoolExpr, BoolExpr];
}

/** args [condition, then, else]. */
export interface ColorIfOp {
  op: "if";
  /** Items: ≥ 3. */
  args: [BoolExpr, ColorExpr, ColorExpr];
}

/** Piecewise constant: out[i], where i is the number of thresholds in `at` that `value` is at or above. `out` has one more entry than `at`. */
export interface NumberStepsOp {
  op: "steps";
  value: NumberExpr;
  /** Items: 1–32. */
  at: NumberExpr[];
  /** Items: 2–33. */
  out: NumberExpr[];
}

/** Piecewise constant text; see numberStepsOp. */
export interface StringStepsOp {
  op: "steps";
  value: NumberExpr;
  /** Items: 1–32. */
  at: NumberExpr[];
  /** Items: 2–33. */
  out: StringExpr[];
}

/** Piecewise constant bool; see numberStepsOp. */
export interface BoolStepsOp {
  op: "steps";
  value: NumberExpr;
  /** Items: 1–32. */
  at: NumberExpr[];
  /** Items: 2–33. */
  out: BoolExpr[];
}

/** Piecewise constant colour (colour rules); see numberStepsOp. */
export interface ColorStepsOp {
  op: "steps";
  value: NumberExpr;
  /** Items: 1–32. */
  at: NumberExpr[];
  /** Items: 2–33. */
  out: ColorExpr[];
}

// scene.schema.json (urn:infopanel:scene:1)

/**
 * Scene
 *
 * What one item draws: a tree of nodes in the item's local coordinates (pixels, y down, angles in degrees clockwise), with typed expressions over the item's inputs, the clock, its layout box, named values and state cells. Format infopanel.scene/1; see docs/scene.md.
 */
export interface Scene {
  format: "infopanel.scene/1";
  /**
   * Capabilities this scene needs beyond version 1.0 (see docs/versioning.md). An engine that lacks one shows the item as unsupported.
   * Items: ≤ 32.
   * Unique items.
   */
  requires?: Capability[];
  /** The inputs the scene reads, by name. An item binds each to a sensor (its `bindings`). */
  inputs?: { [key: string]: InputDecl };
  /** Named expressions, evaluated at most once per tick and read with {"op": "value"}. */
  values?: { [key: string]: AnyExpr };
  /** State cells: values that carry over from tick to tick (smoothing, rate limits, peak hold). Each cell's name is its instance id (see docs/identity.md). */
  state?: { [key: string]: StateCell };
  /** Drawn in order: the first is at the back. */
  nodes: Node[];
}

export interface InputDecl {
  /** number: a numeric sensor (value, statistics, unit, history). text: a text sensor. table: a table sensor. */
  type: "number" | "text" | "table";
  /**
   * A short human-readable name for a client to show.
   * Length: 1–64.
   */
  label?: string;
}

/** On the first tick the cell takes `init`; on each later tick it takes `next`, evaluated with the previous values of all cells and {"op": "dt"}. The cell's type is the common type of `init` and `next` (they must have one), and every read of the cell is checked against it. */
export interface StateCell {
  init: AnyExpr;
  next: AnyExpr;
}

export type Node = GroupNode | RectNode | EllipseNode | ArcNode | LineNode | PathNode | PolylineNode | TextNode | SeriesNode | TableNode | MediaNode;

/**
 * Whether the node is drawn this tick.
 * @default true
 */
export type Visible = BoolExpr;

/**
 * 0–1, clamped. On a group it applies to the composited children as a whole.
 * @default 1
 */
export type Opacity = NumberExpr;

/** Children drawn in order, optionally transformed, clipped, blended and with effects. Order of application: transform, clip, children, effects, then opacity and blend when compositing onto what is below. */
export interface GroupNode {
  kind: "group";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /**
   * Applied as listed: the first step is outermost (as in an SVG transform list).
   * Items: ≤ 8.
   */
  transform?: TransformStep[];
  clip?: ClipShape;
  blend?: BlendMode;
  /**
   * Applied in order to the group's composited children.
   * Items: ≤ 4.
   */
  effects?: Effect[];
  children: Node[];
}

export interface RectNode {
  kind: "rect";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  /** Width; a negative value draws nothing. */
  w: NumberExpr;
  /** Height; a negative value draws nothing. */
  h: NumberExpr;
  r?: CornerRadii;
  fill?: Paint;
  stroke?: Stroke;
}

/** One radius for every corner, or [top-left, top-right, bottom-right, bottom-left]. Each is clamped to half the shorter side. */
export type CornerRadii = NumberExpr | [NumberExpr, NumberExpr, NumberExpr, NumberExpr];

export interface EllipseNode {
  kind: "ellipse";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
  rx: NumberExpr;
  ry: NumberExpr;
  fill?: Paint;
  stroke?: Stroke;
}

/** A circular arc from `start` through `sweep` degrees (clockwise when positive; 0° points along +x). close "sector": the region between radius `inner` and `r` (a pie when `inner` is 0). close "open": the arc curve at radius `r` only, for stroking. */
export interface ArcNode {
  kind: "arc";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
  r: NumberExpr;
  /** @default 0 */
  inner?: NumberExpr;
  /** @default 0 */
  start?: NumberExpr;
  /** Clamped to −360…360. */
  sweep: NumberExpr;
  /** @default "sector" */
  close?: "sector" | "open";
  fill?: Paint;
  stroke?: Stroke;
}

export interface LineNode {
  kind: "line";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  x1: NumberExpr;
  y1: NumberExpr;
  x2: NumberExpr;
  y2: NumberExpr;
  stroke: Stroke;
}

/** A static outline in SVG path syntax (M, L, H, V, C, S, Q, T, A, Z and their relative forms). Move it with a group's transform. */
export interface PathNode {
  kind: "path";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** Length: 1–65536. */
  d: string;
  fillRule?: FillRule;
  fill?: Paint;
  stroke?: Stroke;
}

/** Straight segments through points that may move with expressions; closed, it is a polygon. */
export interface PolylineNode {
  kind: "polyline";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** Items: ≥ 2. */
  points: Point[];
  /** @default false */
  closed?: boolean;
  fillRule?: FillRule;
  fill?: Paint;
  stroke?: Stroke;
}

/** Items: ≥ 2. */
export type Point = [NumberExpr, NumberExpr];

/** @default "nonzero" */
export type FillRule = "nonzero" | "evenodd";

/** Shaped text. Without `w` it is one line (or its explicit lines) as wide as it measures, aligned on `x` by `align`; with `w` it is laid out in that box (wrap, ellipsis, marquee, fit). See docs/smart-nodes.md. */
export interface TextNode {
  kind: "text";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  /** Box width. Absent: automatic. */
  w?: NumberExpr;
  /** Box height, used by valign, clip, ellipsis and fit. Absent: automatic. */
  h?: NumberExpr;
  /** The text, or runs of text with their own font and paint. */
  text: StringExpr | TextSpan[];
  font: Font;
  /** @default "#000000" */
  fill?: Paint;
  stroke?: Stroke;
  /** @default "start" */
  align?: "start" | "center" | "end";
  /**
   * With `h`: where the text sits in the box (baseline places it as top does). Without: which part of the text block `y` names (baseline: the first line's baseline).
   * @default "top"
   */
  valign?: "top" | "middle" | "bottom" | "baseline";
  /** @default "none" */
  wrap?: "none" | "word";
  /** Range: 1–1000. */
  maxLines?: number;
  /**
   * What happens when the text is larger than the box: visible (drawn past it), clip, ellipsis (the last line ends with …, cut at a word boundary, or between characters inside a word wider than the box), marquee (one line scrolls left; needs `w`).
   * @default "visible"
   */
  overflow?: "visible" | "clip" | "ellipsis" | "marquee";
  marquee?: {
    /**
     * Pixels per second, at least 1.
     * @default 30
     */
    speed?: NumberExpr;
    /**
     * Pixels between the end of the text and its next repeat.
     * @default 40
     */
    gap?: NumberExpr;
  };
  /** Shrink the font (every span in proportion) until the text fits the box (`w`, and `h` when set), down to `min` pixels. */
  fit?: {
    min: NumberExpr;
  };
  /** Line height as a multiple of the font size. Absent: the font's own. */
  lineHeight?: NumberExpr;
  /**
   * Extra pixels after each character.
   * @default 0
   */
  letterSpacing?: NumberExpr;
  /** @default false */
  underline?: boolean;
  /** @default false */
  strike?: boolean;
}

export interface TextSpan {
  text: StringExpr;
  font?: FontOverride;
  fill?: Paint;
  underline?: boolean;
  strike?: boolean;
}

export interface Font {
  /**
   * A font family the engine has. A missing family falls back to the engine's default family and is reported.
   * Length: 1–128.
   */
  family: string;
  /** Pixels (the em size), clamped to 1–2048. */
  size: NumberExpr;
  /**
   * Range: 1–1000.
   * @default 400
   */
  weight?: number;
  /** @default false */
  italic?: boolean;
}

/** Replaces the node's font fields that are present. */
export interface FontOverride {
  /** Length: 1–128. */
  family?: string;
  size?: NumberExpr;
  /** Range: 1–1000. */
  weight?: number;
  italic?: boolean;
}

/** A number input's history drawn in a box, newest sample at the right edge, one sample every `pitch` pixels to the left, clipped to the box. y = bottom − clamp((v − min) ÷ (max − min), 0, 1) × h. line: a polyline through the samples (stroke). area: the polyline closed down to the bottom (fill, then the line's stroke). bars: one bar per sample from the bottom, `barWidth` wide, right edge on the sample. */
export interface SeriesNode {
  kind: "series";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  input: Name;
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  w: NumberExpr;
  h: NumberExpr;
  min: NumberExpr;
  max: NumberExpr;
  /** @default "line" */
  mode?: "line" | "area" | "bars";
  /**
   * Pixels between samples, at least 0.25.
   * @default 1
   */
  pitch?: NumberExpr;
  /**
   * At most this many samples. Absent: as many as fit (floor(w ÷ pitch) + 1).
   * Range: 1–4096.
   */
  count?: number;
  /** bars only. Absent: pitch. */
  barWidth?: NumberExpr;
  fill?: Paint;
  stroke?: Stroke;
}

/** Rows of a table input as text: a header row (the column names or `title`) when `header` is true, then up to `rows` rows (0: the header only), one `rowHeight` apart. Columns sit side by side, `gap` apart. Each cell is laid out as text in its column's width (`wrap`, `maxLines`, `overflow`); its first line is centred in its row and further lines run over the rows below. `underline` and `strike` decorate every cell. See docs/smart-nodes.md. */
export interface TableNode {
  kind: "table";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  input: Name;
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  /** Items: 1–16. */
  columns: TableColumn[];
  /**
   * 0: the header only.
   * Range: 0–100.
   * @default 10
   */
  rows?: number;
  /** @default true */
  header?: boolean;
  /** Each cell's first line is centred vertically in it. Absent: the font's line height. */
  rowHeight?: NumberExpr;
  /** @default 0 */
  gap?: NumberExpr;
  font: Font;
  /** @default "#000000" */
  fill?: Paint;
  stroke?: Stroke;
  headerFont?: FontOverride;
  headerFill?: Paint;
  /** @default "none" */
  wrap?: "none" | "word";
  /**
   * Range: 1–1000.
   * @default 1
   */
  maxLines?: number;
  /** @default "ellipsis" */
  overflow?: "visible" | "clip" | "ellipsis";
  /** @default false */
  underline?: boolean;
  /** @default false */
  strike?: boolean;
}

export interface TableColumn {
  /** The table's column by index (0 first) or by name. A column the table doesn't have is skipped: nothing drawn, no width taken. */
  column: number | string;
  /** 0 or less: the column takes no width and doesn't cut or wrap its cells. */
  w: NumberExpr;
  /** @default "start" */
  align?: "start" | "center" | "end";
  /** Header text. Absent: the column's name. */
  title?: StringExpr;
}

/** An image (still or animated) from an asset, a sequence of assets picked by an index (with optional cross-fade), or a configured provider. Animated media plays on the tick clock. See docs/smart-nodes.md. */
export interface MediaNode {
  kind: "media";
  id?: NodeId;
  visible?: Visible;
  opacity?: Opacity;
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  /** Absent: the media's natural width (or kept in proportion to `h`). */
  w?: NumberExpr;
  /** Absent: the media's natural height (or kept in proportion to `w`). */
  h?: NumberExpr;
  source: AssetSource | ProviderSource | SequenceSource;
  /**
   * fill: stretch to the box. contain, cover: scale keeping proportions. none: natural size. cover and none are clipped to the box, as CSS object-fit is.
   * @default "fill"
   */
  fit?: "fill" | "contain" | "cover" | "none";
  /**
   * Where contained, covered or natural-size media sits in the box, as fractions of the free space ([0.5, 0.5]: centred).
   * Items: ≥ 2.
   */
  align?: [number, number];
  /** @default "loop" */
  playback?: "loop" | "once" | "still";
  /**
   * Playback rate, clamped to 0–16.
   * @default 1
   */
  speed?: NumberExpr;
  /** @default "linear" */
  sampling?: "linear" | "nearest";
}

export interface AssetSource {
  asset: BlobId;
}

/** Media from a provider configured on the engine (capability media.provider). `ref` is passed to the provider; the engine never fetches anything that isn't configured. */
export interface ProviderSource {
  /** Pattern: `^[a-z][a-z0-9-]{0,31}$`. */
  provider: string;
  ref: StringExpr;
}

/** Frames picked by `index` (0 first, clamped to the range). With crossfade, a fractional index draws frame floor(index) and, over it, frame ceil(index) at opacity index − floor(index). */
export interface SequenceSource {
  /** Items: ≥ 1. */
  sequence: AssetSource[];
  index: NumberExpr;
  /** @default false */
  crossfade?: boolean;
}

/** A colour (literal or expression) or a gradient. Gradient geometry is in the node's local coordinates. */
export type Paint = ColorExpr | LinearPaint | RadialPaint | SweepPaint | ComposePaint;

/**
 * 2–16 colour stops; `at` is clamped to 0–1 and stops are used in the order given.
 * Items: 2–16.
 */
export type Stops = Stop[];

export interface Stop {
  at: NumberExpr;
  color: ColorExpr;
}

/**
 * Outside 0–1: pad (extend the end colours), repeat, reflect.
 * @default "pad"
 */
export type Spread = "pad" | "repeat" | "reflect";

export interface LinearPaint {
  type: "linear";
  x1: NumberExpr;
  y1: NumberExpr;
  x2: NumberExpr;
  y2: NumberExpr;
  stops: Stops;
  spread?: Spread;
}

export interface RadialPaint {
  type: "radial";
  cx: NumberExpr;
  cy: NumberExpr;
  r: NumberExpr;
  stops: Stops;
  spread?: Spread;
}

/** Colours around (cx, cy) from angle `start` (0° along +x, clockwise) to `end`. */
export interface SweepPaint {
  type: "sweep";
  cx: NumberExpr;
  cy: NumberExpr;
  /** @default 0 */
  start?: NumberExpr;
  /** Absent: start + 360. */
  end?: NumberExpr;
  stops: Stops;
  spread?: Spread;
}

/** Two paints combined per pixel: `src` blended onto `dst` with `blend`, then drawn as one paint. */
export interface ComposePaint {
  type: "compose";
  blend: BlendMode;
  dst: Paint;
  src: Paint;
}

export interface Stroke {
  paint: Paint;
  /** Pixels, centred on the outline; 0 or less draws nothing. */
  width: NumberExpr;
  /** @default "butt" */
  cap?: "butt" | "round" | "square";
  /** @default "miter" */
  join?: "miter" | "round" | "bevel";
  /**
   * Range: 1–100.
   * @default 4
   */
  miterLimit?: number;
  /**
   * Alternating dash and gap lengths in pixels.
   * Items: 2–16.
   */
  dash?: NumberExpr[];
  /** @default 0 */
  dashOffset?: NumberExpr;
  /**
   * Draw only from this fraction of the outline's length (0–1).
   * @default 0
   */
  trimStart?: NumberExpr;
  /**
   * Draw only up to this fraction of the outline's length (0–1).
   * @default 1
   */
  trimEnd?: NumberExpr;
}

/**
 * How a group or paint combines with what is below (W3C Compositing and Blending; plus adds the colours).
 * @default "normal"
 */
export type BlendMode = "normal" | "multiply" | "screen" | "overlay" | "darken" | "lighten" | "color-dodge" | "color-burn" | "hard-light" | "soft-light" | "difference" | "exclusion" | "hue" | "saturation" | "color" | "luminosity" | "plus";

export type TransformStep = TranslateStep | RotateStep | ScaleStep | SkewStep | MatrixStep;

export interface TranslateStep {
  type: "translate";
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
}

/** Rotation by `angle` degrees clockwise about (cx, cy). */
export interface RotateStep {
  type: "rotate";
  angle: NumberExpr;
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
}

/** Scale about (cx, cy); a negative factor mirrors. */
export interface ScaleStep {
  type: "scale";
  x: NumberExpr;
  y: NumberExpr;
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
}

/** Skew by angles in degrees along x and y (each clamped to −89…89). */
export interface SkewStep {
  type: "skew";
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
}

/** An affine matrix [a, b, c, d, e, f]: x' = a·x + c·y + e, y' = b·x + d·y + f. */
export interface MatrixStep {
  type: "matrix";
  /** Items: ≥ 6. */
  m: [number, number, number, number, number, number];
}

/** Children are drawn only inside this shape (antialiased), in the group's coordinates after its transform. */
export type ClipShape = RectClip | EllipseClip | ArcClip | PathClip;

export interface RectClip {
  kind: "rect";
  /** @default 0 */
  x?: NumberExpr;
  /** @default 0 */
  y?: NumberExpr;
  w: NumberExpr;
  h: NumberExpr;
  r?: CornerRadii;
}

export interface EllipseClip {
  kind: "ellipse";
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
  rx: NumberExpr;
  ry: NumberExpr;
}

/** The sector region of an arc (see arcNode). */
export interface ArcClip {
  kind: "arc";
  /** @default 0 */
  cx?: NumberExpr;
  /** @default 0 */
  cy?: NumberExpr;
  r: NumberExpr;
  /** @default 0 */
  inner?: NumberExpr;
  /** @default 0 */
  start?: NumberExpr;
  sweep: NumberExpr;
}

export interface PathClip {
  kind: "path";
  /** Length: 1–65536. */
  d: string;
  fillRule?: FillRule;
}

export type Effect = BlurEffect | ShadowEffect | GlowEffect;

/** Gaussian blur of the group's content. */
export interface BlurEffect {
  type: "blur";
  /** Standard deviation in pixels, clamped to 0–64. The blur reaches 3 sigma. */
  sigma: NumberExpr;
}

/** The content's coverage, filled with `color`, offset by (dx, dy) and blurred, drawn under the content. In the group's coordinates after its transform (the offset turns with the group); not clipped by the group's clip. */
export interface ShadowEffect {
  type: "shadow";
  /** @default 0 */
  dx?: NumberExpr;
  /** @default 0 */
  dy?: NumberExpr;
  /** Clamped to 0–64. */
  sigma: NumberExpr;
  color: ColorExpr;
}

/** A shadow with no offset: the content's coverage filled with `color`, blurred, drawn under the content; not clipped by the group's clip. */
export interface GlowEffect {
  type: "glow";
  /** Clamped to 0–64. */
  sigma: NumberExpr;
  color: ColorExpr;
}

